SELECT COUNT(*) FROM (
  SELECT DISTINCT f.item_id
  FROM fdbk_g1 f
  LEFT JOIN attrs_g1 a ON f.item_id = a.item_id
  WHERE a.item_id IS NULL
);

SELECT COUNT(*) FROM (
  SELECT DISTINCT f.ref_id
  FROM fdbk_g1 f
  LEFT JOIN attrs_g1 a ON f.ref_id = a.ref_id
  WHERE a.ref_id IS NULL
);

SELECT ROUND(
    (SELECT AVG(LENGTH(body)) FROM fdbk_g1 WHERE body IS NOT NULL AND body != '' AND verified_status IS NULL AND ref_id IN (SELECT ref_id FROM items_g1 WHERE status = 'active')) -
    (SELECT AVG(LENGTH(body)) FROM fdbk_g1 WHERE body IS NOT NULL AND body != '' AND verified_status IS NOT NULL AND ref_id IN (SELECT ref_id FROM items_g1 WHERE status = 'active')),
    1
) AS diff;

SELECT ROUND(
    (SELECT COUNT(*) FROM product_attributes_g3) * 1.0 / 
    (SELECT COUNT(*) FROM attrs_g3_legacy),
    2
) as ratio;

SELECT ROUND(
    100.0 * SUM(CASE WHEN avg_rtg >= 4.5 THEN 1 ELSE 0 END) / COUNT(*),
    1
) as percentage
FROM items_g2
WHERE avg_rtg IS NOT NULL AND prc_usd > 0;
